<?php $tables=[['Members by membership type',$reports['members_by_type']['membership_type']??[]],['Members by province',$reports['members_by_province']['province']??[]],['Members by profession',$reports['members_by_profession']['profession']??[]],['Account statuses',$reports['account_statuses']??[]],['Cash received by year',$reports['revenue_by_year']??[]],['Cash by membership type',$reports['cash_by_type']['membership_type']??[]],['Cash by province',$reports['cash_by_province']['province']??[]],['Cash by profession',$reports['cash_by_profession']['profession']??[]],['Membership trend '.$year,$reports['membership_trend']??[]]];?><div class="row g-4"><?php foreach($tables as [$title,$rows]):?><div class="col-lg-4"><div class="card h-100"><div class="card-body"><h2 class="h5"><?=e($title)?></h2><?php if(!$rows):?><p class="text-secondary mb-0">No data available.</p><?php else:?><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Category</th><th class="text-end">Total</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e($row['label']??'Unassigned')?></td><td class="text-end"><?=e(number_format((float)($row['total']??0),2))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div></div></div><?php endforeach;?></div>